'use strict'

var util = require('util')
var assert = require('assert')
var Q = require('q')

var EventEmitter = require('events').EventEmitter

var TafClient = require('@taf/taf-rpc').Communicator.New()
var ConfigParser = require('@taf/taf-utils').Config
var taf = require('./ConfigFProxy').taf
var common = require('./lib/common')

var fileHelper = require('./lib/fileHelper')

var parseConf = function (content, configFormat) {
  var ret = content
  if (configFormat === 'c') {
    var configParser = new ConfigParser()
    configParser.parseText(content, 'utf8')
    ret = configParser.data
  } else if (configFormat === 'json') {
    ret = JSON.parse(content)
  }

  return ret
}

function tafConfigHelper (options) {
  var self = this
  var proxyName = 'taf.tafconfig.ConfigObj'
  var confFilePath = null

  if (process.env.TAF_CONFIG) {
    confFilePath = process.env.TAF_CONFIG
  } else {
    if (options && options.confFile) {
      confFilePath = options.confFile
    }
  }

  if (confFilePath) {
    TafClient.initialize(confFilePath)
    var configParser = new ConfigParser()
    configParser.parseFile(confFilePath, 'utf8')

    this.app = configParser.get('taf.application.server.app', '')
    this.server = configParser.get('taf.application.server.server', '')
    this.localip = configParser.get('taf.application.server.localip', '')
    this.containername = configParser.get('taf.application.server.container', '')
    var enableset = configParser.get('taf.application.enableset', '')
    if (enableset.toLowerCase() === 'y') {
      this.setdivision = configParser.get('taf.application.setdivision', '')
    }

    proxyName = configParser.get('taf.application.server.config', '')
  }

  // 本地运行
  if (!process.env.TAF_CONFIG) {
    if (options && options.tafConfigObjProxyName) {
      proxyName = options.tafConfigObjProxyName
    } else {
      // 非taf平台，又没有设置taf.tafconfig.ConfigObj服务的地址，那么就使用默认的代理
      proxyName = 'taf.tafconfig.ConfigObj@tcp -h 172.16.8.121 -t 60000 -p 10000'
    }
  }

  if (options) {
    if (options.app) {
      this.app = options.app
    }

    if (options.server) {
      this.server = options.server
    }

    if (options.host) {
      this.localip = options.host
    }
  }

  assert(this.app && this.server, 'can not get app or server name')

  this.options = options
  this.prx = TafClient.stringToProxy(taf.ConfigProxy, proxyName)
  this.setTimeout()

  this.setMaxListeners(0)

  process.on('message', function (obj) {
    if (obj.cmd === 'taf.loadconfig') {
      self.loadConfig(obj.data).then(function (configContent) {
        self.emit('configPushed', obj.data, configContent)
      }, function () {}).done()
    }
  })
}
util.inherits(tafConfigHelper, EventEmitter)

// 把参数转化为taf.ConfigInfo实例
tafConfigHelper.prototype.getConfigInfoObj = function (configOptions, isForList, isListAllFun) {
  var configInfo

  if (isListAllFun && isForList) {
    if (configOptions instanceof taf.GetConfigListInfo) {
      return configOptions
    }
    configInfo = new taf.GetConfigListInfo()
  } else {
    if (configOptions instanceof taf.ConfigInfo) {
      return configOptions
    }
    configInfo = new taf.ConfigInfo()
  }

  configInfo.appname = this.app

  var servername = this.server
  var bAppOnly = false
  var host = this.localip
  var filename = ''

  if (configOptions) {
    if (typeof configOptions === 'object') {
      filename = configOptions.filename || ''
      if (configOptions.bAppOnly) {
        bAppOnly = true
      } else {
        if (configOptions.servername) {
          servername = configOptions.servername
        }
      }
      host = configOptions.host || ''
    } else {
      filename = configOptions
    }
  }

  if (servername === '') {
    bAppOnly = true
  }

  if (bAppOnly) {
    servername = ''
  }

  configInfo.servername = servername
  configInfo.host = host || ''
  configInfo.setdivision = this.setdivision || ''
  configInfo.containername = this.containername || ''
  configInfo.bAppOnly = bAppOnly

  if (!isForList) {
    configInfo.filename = filename
  } else {
    // 拉List的时候set要为空，拉内容要填写
    // @2016-05-25，去掉上面的潜规则
    // configInfo.setdivision = ""
  }

  return configInfo
}

/*
 @description:加载服务默认的配置项,并且转换为json
 @param：configFormat {string} "c":c++格式的配置项，默认值。"json"：配置项是json格式的
 */
tafConfigHelper.prototype.loadServerObject = function (configFormat) {
  var _configFormat = configFormat || 'c'
  return this.loadConfig(this.server + '.conf', _configFormat)
}

/*
 @author:jerrewu
 @date:2016-03-24
 @description:获取节点的配置内容
 @return {String} configContent:返回TAF配置项的文本内容
 */
tafConfigHelper.prototype.loadConfig = function (configOptions) {
    var dfd = Q.defer();
    var configInfo = this.getConfigInfoObj(configOptions);
    
    this.prx.loadConfigByInfo(configInfo).then(function (retData) {
        var content = retData.response.arguments.config;

        if (process.env.TAF_CONFIG) {
            fileHelper.write(configInfo, content).then().catch();
        }

        dfd.resolve(content);
    }, function (err) {
        var errMsg = common.handleRpcErr(err);

        if (process.env.TAF_CONFIG) {
            console.log('TAF-Config[Load error]', 'RPC[loadConfigByInfo]', `Error[${errMsg}]`);

            fileHelper.read(configInfo).then(content => {
                dfd.resolve(content);
            }).catch(retErr => {
                dfd.reject("loadConfigByInfo error" + errMsg + "|" + retErr);
            });
        } else {
            dfd.reject("loadConfigByInfo error" + errMsg);
        }
    }).done();

    return dfd.promise;
}

/*
 @author:jerrewu
 @date:2016-03-24
 @description:获取节点的配置内容
@return {Object} configObject:返回TAF配置项的object
 */
tafConfigHelper.prototype.loadConfigObject = function (configOptions,configFormat) {
    return this.loadConfig(configOptions).then((configText)=>
    {
        return parseConf(configText, configFormat);
    })
}

/*
 @author:jerrewu
 @date:2016-03-24
 @description:获取节点的配置列表
 */
tafConfigHelper.prototype.getConfigList = function (configOptions) {
  var configInfo = this.getConfigInfoObj(configOptions, true, true)

  // 必须传空
  configInfo.host = ''

  // 2016-05-26:拉列表的时候，不应该调用ListConfigByInfo方法，改为ListAllConfigByInfo
  return this.prx.ListAllConfigByInfo(configInfo).then(function (retData) {
    return retData.response.arguments.vf.value
  })
}

/*
 @author:jerrewu
 @date:2016-03-24
 @description:获取节点的所有配置项，promise返回一个object，key是文件名，value是配置内容
 */
tafConfigHelper.prototype.getAllConfigData = function (configOptions, configFormat) {
  var configInfoContent = this.getConfigInfoObj(configOptions, false)
  var dfd = Q.defer()
  var self = this

  this.getConfigList(configOptions).then(function (configList) {
    var pActions = []

    configList.forEach(function (cItem) {
      var fConfig = configInfoContent
      fConfig.filename = cItem
      pActions.push(self.loadConfig(fConfig).then(function (configContent) {
        return {filename: cItem, content: configContent}
      }))
    })

    Q.all(pActions).then(function (allData) {
      var retObj = {}

      allData.forEach(function (cItem) {
        retObj[cItem.filename] = parseConf(cItem.content, configFormat)
      })

      dfd.resolve(retObj)
    }).catch(function (error) {
      dfd.reject('load connfig error', error)
    })
  })

    return dfd.promise;
}

/*
 @author:jerrewu
 @date:2016-03-24
 @description:获取服务级别的配置列表,host=''
 */
tafConfigHelper.prototype.getServerConfigList = tafConfigHelper.prototype.getConfigList

/*
 @author:jerrewu
 @date:2016/6/24
 @description:设置timeout,由于 taf.tafconfig 服务调用响应慢问题，所以默认值为30s,入参是ms
 */
tafConfigHelper.prototype.setTimeout = function (iTimeout) {
  var timeout = iTimeout || 5 * 1000
  this.prx.setTimeout(timeout)
}

exports = module.exports = tafConfigHelper
